assert.ok(fs.existsSync(path.join(buildDir,'index.html')));
const server = http.createServer((request,response) => {
  let file=path.join(buildDir,decodeURIComponent(request.url.split('?')[0]));
  if (!fs.existsSync(file) || fs.statSync(file).isDirectory()) file=path.join(buildDir,'index.html');
  response.setHeader('Content-Type',({'.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json','.svg':'image/svg+xml','.woff2':'font/woff2'})[path.extname(file)] || 'application/octet-stream');
  fs.createReadStream(file).pipe(response);
});
